import{_ as t,c as s,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易图通变卷八","description":"易图通变 - 易图通变卷八","frontmatter":{"title":"易图通变卷八","description":"易图通变 - 易图通变卷八"},"headers":[],"relativePath":"zh/classics/yitu-tongbian/009.md","filePath":"zh/classics/yitu-tongbian/009.md"}'),r={name:"zh/classics/yitu-tongbian/009.md"};function o(l,a,c,d,p,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易图通变卷八",tabindex:"-1"},[i("易图通变卷八 "),e("a",{class:"header-anchor",href:"#易图通变卷八","aria-label":"Permalink to “易图通变卷八”"},"​")],-1),e("p",null,"钦定四库全书",-1),e("p",null,"宋雷思齐撰衍数",-1),e("p",null,"天地之数五十有五。以天数之一、三、五、七、九而二十有五，地数之二、四、六、八、十而三十，宜乎断断乎不得有所损。盖而大衍之数遽损其五，而特谓之五十，是以求其理而不得，稽其数而不合，卒莫之要其宿。人莫不有说，说莫不有其理之似，而卒未有会其真是者，古犹今也。列子之书，儒者梏于传习，盖所不取、所不观。殊不察其首篇谓圣人因阴阳以统天地。夫有形生于无形，则天地安从生？故曰：有太易，有太初，有太始，有太素。太易者，未见气者也。太初者，气之始也。太始者，形之始也。太素者，质之始也。气形质具而未相离，故曰浑沦。浑沦者，言万物相浑沦而未相离，故曰易也。易变而为一，一者，形变之始也。是说也，重见于易纬乾凿度，亦固谓然也。由是而观，则易之有太极，而太极也者，特浑沦之寄称尔。浑沦而上，既有谓易、谓初、谓始、谓素，凡四其称，而至于浑沦而五，故以浑沦为太极，是之谓五太也。是则太极也者，既先含其五于中矣。故天地之数五十有五，而大衍之数乃五十者，既虚其太极已上之五，而取用于五十之妙也。大传曰：「生生之谓易，成象之谓乾，效法之谓坤，极数知来之谓占，通变之谓事，阴阳不测之谓神。」盖谓是也。由是知易有太极之为一，而一所以为形变之始矣。既谓易有太极，而又谓为生生之谓易，而遂继以「成象之谓乾」，而不及太极，何也？是未识夫易者，盖阴阳之总，而太极者，特阴阳变化之宗会焉尔。故曰「易变而为一」，一者，形变之始也。易由太极以标其一，所以为成象之谓乾，即所谓形变之始，而乃所以为一也。由乾分其一□以为二□而始谓之坤，是大衍五十不用之一，象之为易有太极之一，而一之分为□，所以象两。夫两不谓二而谓之象两，正以□之分也。故大衍之五十，先尊其太极不用之一，以为生生之本，而谓其用四十有九者，盖由一之二，其一以生两仪□是分而为二以象两一又参其一以为三才之道，☰是挂一以象三□复四其一为四象，则北南东西之判，冬夏春秋之序，水火木金之位，莫不由是以著，则所以揲之以四，以象四时者也，而河图之数所以四十者也。然天地之数五十有五，大衍之数则五十，天五既无位于四象，地十又无位于八卦，何其不合若是之甚也。天五之有数而无位者，五之文，古之体为□，象一四交互以为五。今之体为□，见阴阳之四交变于二之中以为五，而十之体亦兆见于此。五固为土，而土之文为□，为十，为一，其始于一，而中于五，而终于十，而复归于一乎？土亦无正位，故四象无五，八卦无十也。盖尝探索于天地之数，五十有五之元矣。四象之一二三四，所以为八卦者，不过再用一二三四，而各以五参之为六七八九尔，其数止四十。八卦之一九而二八，三七而四六，相交而□十之，其数亦止此四十。未尝有天五地十之定位者，正以天五与地十，以五乘十，而为此大衍之五十也。何以明之？五之妙用，伍北坎之一，以五而合六为西北之乾，伍东震之三，以五而合八为东北之艮者，先其方之正，后其维之偏。伍西南坤之二，以五而合七于西方之兑。伍东南巽之四，以五而合九于正南面之离者，先其维之偏，后其方之正。故阳奇得五而为阴耦，阴耦得五而为阳奇，所以分阴分阳，八卦以之成列。至于十之用，则什离南之九以相对而交十于坎北之一，什兑西之七相对，而交十于震东之三，是阳数自交于阳，而各立其方之正。什艮东北之八以相对，而交十于巽东南之四，是阴数自交于阴，而均就其维之偏。因而各虚五于中，则又皆十五之变。所以刚柔相摩，八卦相荡相错，变而通之，推而行之者，见天五地十，独专五十之用也。故衍之于揲，必以四以象四时，五十之用，正在于是。其揲之以四者，盖由五其一二三四于上，而十其六七八九于下，足以明之。五与天一合而成六，则四其六而二十有四为老阴坤之策。五与地二合而成七，则四其七而二十有八为少阳震、坎、艮之策。五与天三合而成八，则四其八而三十有二为少阴巽、离兑之策。五与地四合而成九，则四其九而三十有六为老阳乾之策。故少阴阳之七八不变，合之而十五，以为重卦之成画；老阴阳之九六所以变者，合之而亦十五，以为重卦之动爻。易之变通配四时，故四四而揲以象之，其四营成易，莫不由此。河图之实数四十，虚天五之二五，而以地十衍之而五十也。夫四营成易，四四而揲，每爻之揲凡三，每揲其蓍以合左右之奇，或一二三而四，或三一而四，或二二而四。其或左奇既先四，则右奇后亦必四，因二其四，耦之成八，以纪其数者，奇必有耦也。奇四而耦八，亦见数之四十增八者，河图四十而成八卦也。然其所揲之四，未尝五与九也。今揲蓍者必谓初揲不五则九，始由易疏谓第一变之奇不五则九，第二揲、第三揲之奇始皆不四则八，原其第一揲误以未揲之先，所谓挂一之蓍同在数中，以自乱其四而然也。盖所揲之奇，四之上加一则五，八之上加一则九，所以见也。殊不识此一之加为五为九，无成亏于所揲之四，而徒为扰扰耳。且夫挂一自当四营之一，营在分而象两之后，揲之以四之先，元未以之与于揲也。若非以挂一之一误于自乱，则安得谓第二揲第三揲而不四则八也。夫每更左右两揲四始为一变，传谓十有八变而成卦，则凡揲之变，固不容有所异也，安得每三揲之中，第一揲为不五则九也。如是则十有八变中，独六变若是之异，若于中六变独异，则又安得总谓十有八变也哉？此孔疏始为此误，而后之来者既不加察，而传信传疑，愈说愈纷，卒未能有以正其误者，千载良一慨也。若谓挂一者，合置于奇数中之用以为数，则至于扐而后挂者，又当何以哉？载原其误者，盖泥于衍数五十，其用四十有九，谓挂一之一实在四十有九所用之中，而不识夫挂一者所以揲每变四十有八之用，而计其十有八变之数，则乃所以为用也。岂以夫一而自乱于四十有八所揲之众哉？故所揲之蓍，实行其变者四十有八。标夫挂一者，以纪其变之十有八，固所以为四十有九之用，并与其始太极所不用之一，通为大衍之五十也。所以谓夫「五十」者，「蓍之德员而神」者，其员以七，七七而四十有九。「卦之德方以知」者，其方以八，八八而六十有四。是以七合八之十五，既合而见于蓍卦之数矣。「六爻之义易以贡」者，乃散而分见于乾之用九，坤之用六，以九合六之十五之用，而由五以下，七八九六，无有不著于用者焉。故以五乘十，而所以谓为「大衍五十」也。若是，则由天之与地，自一而至十，五十有五之数，莫不真见其著落。而大衍之五十，与其用四十有九者，亦莫不悉究其诣实。其谓生生之易，成象之乾，效法之坤，极数知来之占，通变之事，于此了然可尽。至于阴阳不测之谓神，神而明之，存乎其人哉！命蓍说卦曰：「昔者圣人之作易也，幽赞于神明而生蓍，参天两地而倚数，观变于阴阳而立卦，发挥于刚柔而生爻。」若是，则蓍岂徒生，数岂虚倚，卦岂苟立，而爻岂谩为哉？因爻画卦，因卦兆数，因数用蓍，以极天下之赜，以鼓天下之动，由此其选也。大传曰：「蓍之德员而神，卦之德方以知，六爻之义易以贡。」此大衍之数之蓍所由著也。大衍之数盖五十其蓍，而其用乃四十有九者，盖已尊其一于不用，以为太极之全体，是所谓「易有太极」者也。乃分其四十有九之蓍，列左右为二以象两，是所谓「太极生两仪」也。两仪者阴阳，阴阳相仪匹而有老少，则两仪已含四象矣。乃左取蓍而挂其一以象三，八卦之画以三而成，则三才之道也。盖以元五十不用之一，与分两之二，兼之而成此三也。是于分两之二，推其一以挂于两之际，所以象人极之立位乎两间也。是则参天两地，而倚数特寓于此不用之一，象两之二，挂一之三，参天也。分而象两，固所以两地者也。于是观变于阴阳而立卦矣。所谓太极不用之一，虽不以为用，而乾阳之始一，实兆乎此，则其用未始不由此以出也。因此乾用之一，以分而为坤体之二，则所谓象两而为两仪，以两仪而一阴一阳，以老少于其位，是两仪已含四象矣。是以继之以象三之一，而分阴分阳，迭柔刚而用之，而象三以画，则四象遂生八卦，而八卦者已成列矣。八卦各三位，八卦而小成，三极之道于是乎见矣。合而言之，是「易有太极，是生两仪，两仪生四象，四象生八卦」，已著于用而成于体矣。然而大衍之数之用，虽略见于分两、挂之始，而未大成也。且太极不用之一，象两之二，挂一之三，虽等列而三位，而其正用之蓍，特不用之一与挂一之一，其实数特二尔。且以五十而始用其二，则未用之蓍正存四十有八，是用河图之数四十以行八卦也。且八卦各六位，以八卦而其位各六而八之，非四十有八者乎？八卦虽八八而六十四，而其为游魂、归魂者凡十有六，不列于正八卦之六位，故其数止于四十有八也。由四十有八而上虚此十六卦为四四以揲之用，乃所以成六十有四也。于是乎观变于阴阳而立卦，则遂发挥于刚柔而生爻。爻也者，效天下之动者也。立天之道曰阴与阳，立地之道曰柔与刚，立人之道曰仁与义。兼三才而两之，故易六画而成卦也。前既以不用之一象两之，挂一之三等而三之，由三而四，故先以分左之蓍揲之以四，以象四时，四时而八节，犹四象生八卦也。故以四行八足以见十六卦之四四，实用六十四卦之八八也。四四之奇所以寄乾，八八之奇所以寄坤。八八之奇虽谓之耦，然亦奇四所协以配，故兼谓之归奇也。所揲之奇，不一则二，不三则四，则归之扐，于是谓之「归奇于扐以象闰」，闰乃余数之所归，故以奇象之，奇亦余也。然后以分右之蓍，四四而揲，所揲之奇四且八之。其得一则先左之奇必三，合之而四。得三则其先左之奇必一，合之而四。得二则其先左之奇亦必二，通合之为四。得四则其先左之奇亦必四，特合之为八。盖左先一而后右三，与左先三而后右一，固皆合四以为奇。而其左先二而后右二，虽亦合之为四，而理乃倍四而耦八也。若左奇既四，右奇亦四，因合而八以为耦。耦虽谓八，亦奇四之分配以成之也。犹坤之□乃乾「□」之所分，故统谓之奇。乃随后右所合之奇、所奇之蓍再扐于左，而兼取左右所奇者挂之，以待第二、第三变，是谓「再扐而后挂」也。然而前挂一之「挂」，则谓于四十有九中先取一蓍以独挂，此扐而后挂之挂，则特谓挂其所奇之蓍也。乃又总前已分二、已挂一与所已过揲之蓍，悉合之以还于大衍之初，是之谓「四营而成易」，而通为第一爻也。所谓四营者，分二者，其一也；挂一者，其二也；揲四，其三也；归奇，终营之四也。其营既毕，所奇既挂，是为第一变之周也。一变之后，存其前所奇之外，以所合前衍过揲之蓍，如第一变之分二之挂一、之揲四之归奇，再扐而后挂其所奇，以合前变之奇，以待第三变也。其第三变，则又如第一、第二变之分二、挂一、揲四、归奇，再扐而合此三变所奇之蓍以数之，以四为少、八为多。三变皆少，则所奇者十二，则其过揲之所存总四九三十有六，为乾之策。三变皆多，则所奇者二十四，则其过揲之所存，四六亦二十有四，为坤之策。两多而一少，则所奇者二十，则其过揲之所存，总四七二十有八，是为震为坎为艮之策。两少而一多，则所奇者十六，则其过揲之所存，总四八三十有二，是为巽、为离为兑之策。凡如是三变竟，始得为一爻之成画，亦必以所奇之策，由初以终，自下而上，层积而纪之，如画卦之三爻然。其奇之四为阳，八为阴，效八卦以取之。两多而一少者，其先四、中八后八为得阳之初，象少阳七之震；☳先八、中四、后八为得阳之中，象少阳七之坎；☵先八、中八后四为得阳之上，象少阳七之艮。☶两少而一多，其先八、中四后四为得阴之初，象少阴八之巽；☴先四、中八后四为得阴之中，象少阴八之离；☲先四、中四、后八为得阴之上，象少阴八之兑。☱凡遇震、坎、艮，则皆画为一，阳爻也；遇巽、离、兑则皆画为□，阴爻也。□□者皆谓之少者，象少者未遽变也。独其三变通得四四四者，特谓为阳之纯，象老阳九之乾，☰乃画为□ 今俗谓「重」。 为老阳九之爻。其三变通得八八八者，特谓为阴之纯，象老阴六之坤，☷乃画为十 今俗谓「交」。 为老阴六之爻。乾为老阳□者，本九奇而变，含六耦之阴。坤为老阴十者，本六耦而变，含九奇之阳。乾坤之画兼谓老者，以老故变也。其必三变始成一画者，寓阴阳变化拟议以定之也。于三变所奇之策，第其四与八之互者，寓乾坤相索生六子意也。凡如是而分，而挂，而揲，且扐，积其奇而合过揲之蓍者三，谓之「变」，始谓一爻之成；又如是而三变，则谓二爻之成；又如是而三变，乃通谓三爻之成，是谓九变。九变备，三爻具，始可当为卦之八者，止三画。三其画而八之，则为八卦成列，谓内卦，谓下卦，谓三微，谓内贞，是谓八卦而小成。是三易所谓「经卦皆八」也。盖必又如是以营，以分，以挂，以揲，以扐，以计其所奇之积。三而三之，以为九变，再成三画以为外卦，为上卦，为三蓍，为外悔。合前九变之三画，是谓六画而成卦。是三易所谓其别皆六十有四，始全其十有八变而成卦，以备六位成章也。其所以变必十有八者，震、坎、艮各五画得十五，用乾之三为十八，而二乾之一、三、五固十八也；巽、离、兑各四画得十二，用坤之六为十八，而三坤之二、四亦十八也。合两十八则为乾之策。四九三十六是前九变每爻四营，积九变之营，固三十六也，倍之则龟之策。七十二、五行之土分王四时，各十八日，四其十八，亦七十二日，各九十日，分土王之十八日，亦各七十二。故积十有八变，每变四营，通十八变，计其营之数，亦七十二。五其七十二，则三百有六十当期之日，故有取于十八变七十二营，以用四十有九蓍也。盖前九变三画分阴阳而列之，不过八卦成列，而象在中。后九变三画迭柔刚而用之，乃因而重之，而爻在中。因其十八变而爻之迭柔刚也，用此柔刚以相摩相荡，相推相易而通其变，引而伸之于六十四卦，惟变所适，是所谓变在其中。由六十四卦触类长之于三百八十四爻之外，则天下之能事诚可毕矣。蓍之德可不谓员，而神于其常用；卦之德可不谓方，以知于其常体；而六爻之义可不谓易，以贡于受命如响之变化者乎？又可不谓「寂然不动，感而遂通天下之故」者乎？故以之通天下之志，成天下之务，定天下之业，而断天下之疑。其于「幽赞于神明而生蓍，参天两地而倚数，观变于阴阳而立卦，发挥于刚柔而生爻」者，蓍岂徒生，数岂虚倚，卦岂苟立，而爻岂谩为哉！果能此道以神明其德，诚可以显道神德行，而酬酢祐神矣。大衍之数五十，其用四十有九，其以是夫。易筮通变卷下。",-1)])])}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
